struct TrieNode {
    TrieNode* children[26];
    bool endOfWord;
    TrieNode() : endOfWord(false) { for (int i = 0; i < 26; i++) children[i] = nullptr; }
};
void insert(TrieNode* root, const char* word) {
    TrieNode* cur = root;
    for (const char* p = word; *p; ++p) {
        int i = *p - 'a';
        if (!cur->children[i]) cur->children[i] = new TrieNode();
        cur = cur->children[i];
    }
    cur->endOfWord = true;
}
int main() {
    TrieNode* root = new TrieNode();
    insert(root, "apple");
    return 0;
}
